from pathlib import Path
import json,html
r=Path(__file__).resolve().parents[1];repo=r.parents[1]
def esc(s):return html.escape(s)
manifest=(repo/'apps/run-importer/app.manifest.json').read_text()
bindings=(repo/'apps/replay-studio/wrangler.jsonc').read_text()
proof=(r/'evidence/verification.log').read_text();proof='\n'.join(x for x in proof.splitlines() if '✔' in x or x.startswith('ℹ'))
checks=(r/'evidence/composer-check.log').read_text();checks='\n'.join(x for x in checks.splitlines() if 'accepted' in x)
